WITH PARAMS AS ( SELECT CASE WHEN TRIM(COALESCE(:VAR_DATA_INICIO, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_INICIO), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_INICIO, '')), '')) END AS DT_INI_IN, CASE WHEN TRIM(COALESCE(:VAR_DATA_FIM, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_FIM), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_FIM, '')), '')) END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_FIM, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), base_bal AS ( SELECT CTACTB, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS saldo_atu, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS fluxo_atu, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI FROM D) THEN VLRLANC ELSE 0 END) AS abertura_atu, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS saldo_ant, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS fluxo_ant, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI_ANT FROM D) THEN VLRLANC ELSE 0 END) AS abertura_ant FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE GROUP BY CTACTB ), ref_vigente AS ( SELECT DET.ID AS ID_DET, (SELECT R.ID FROM DET_DEMONSTRATIVO_REFERENCIA R WHERE R.ID_DET_DEMONSTRATIVO = DET.ID AND (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) <= (SELECT ANO_FIM FROM D) AND EXISTS (SELECT 1 FROM DET_DEMONSTRATIVO_CTACTB C WHERE C.ID_DET_DEMONSTRATIVO_REFERENCIA = R.ID) ORDER BY (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) DESC, R.ANO_REFERENCIA DESC, R.ID DESC LIMIT 1) AS ID_REF FROM DET_DEMONSTRATIVO DET ), regras_contas AS ( SELECT DISTINCT DET.ORDEM, DET.NOME_GRUPO, DET.COD_NOTA_EXPLICATIVA, DETCTACTB.PADRAO_CTACTB, DETCTACTB.SINAL FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO INNER JOIN ref_vigente RV ON RV.ID_DET = DET.ID INNER JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF WHERE EST.ID = 1 AND TRIM(DET.ORDEM) <> '3.3.3' ), regras_excluidas AS ( SELECT DISTINCT DET.ORDEM, DETCTACTB_EXC.PADRAO_CTACTB FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO INNER JOIN ref_vigente RV ON RV.ID_DET = DET.ID INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC DETCTACTB_EXC ON DETCTACTB_EXC.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF WHERE EST.ID = 1 ), contas_mapeadas AS ( SELECT R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVA, R.SINAL, CASE WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.abertura_atu WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.fluxo_atu ELSE B.saldo_atu END AS valor_atu, CASE WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.abertura_ant WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.fluxo_ant ELSE B.saldo_ant END AS valor_ant, ROW_NUMBER() OVER ( PARTITION BY B.CTACTB, R.ORDEM, R.NOME_GRUPO ORDER BY LENGTH(R.PADRAO_CTACTB) DESC, R.PADRAO_CTACTB DESC ) AS rn FROM base_bal B INNER JOIN regras_contas R ON B.CTACTB LIKE R.PADRAO_CTACTB LEFT JOIN regras_excluidas E ON E.ORDEM = R.ORDEM AND B.CTACTB LIKE E.PADRAO_CTACTB WHERE E.PADRAO_CTACTB IS NULL ) SELECT R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVA, IFNULL(SUM(M.valor_atu * M.SINAL), 0) AS VLRLANC_ATU, IFNULL(SUM(M.valor_ant * M.SINAL), 0) AS VLRLANC_ANT, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT ANO_FIM FROM D) AS ANO_USADO FROM (SELECT DISTINCT ORDEM, NOME_GRUPO, COD_NOTA_EXPLICATIVA FROM regras_contas) R LEFT JOIN contas_mapeadas M ON M.ORDEM = R.ORDEM AND M.NOME_GRUPO = R.NOME_GRUPO AND M.rn = 1 GROUP BY R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVA ORDER BY R.ORDEM LIMIT 500;